import { test, expect } from '@playwright/test';

test.describe('Google OAuth Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in using Google OAuth', async ({ page }) => {
    // Verify login page is visible
    const loginPage = page.getByRole('main');
    await expect(loginPage).toBeVisible();

    // Click Google login button using getByRole
    const googleButton = page.getByRole('button', { name: /Sign in with Google/i });
    await expect(googleButton).toBeVisible();
    await googleButton.click();

    // Wait for Google OAuth redirect
    await page.waitForURL(/accounts\.google\.com/);

    // Verify Google consent screen is visible
    const consentScreen = page.getByRole('dialog', { name: /Sign in to Google/i });
    await expect(consentScreen).toBeVisible();

    // Click "Allow" button using getByRole
    const allowButton = page.getByRole('button', { name: /Allow/i });
    await expect(allowButton).toBeVisible();
    await allowButton.click();

    // Wait for successful authentication redirect
    await page.waitForURL(/.*\/dashboard/);

    // Verify user is logged in and redirected to dashboard
    const dashboardHeader = page.getByRole('heading', { name: /Dashboard/i });
    await expect(dashboardHeader).toBeVisible();

    // Verify user profile picture is displayed
    const profilePic = page.getByRole('img', { name: /User profile picture/i });
    await expect(profilePic).toBeVisible();

    // Verify welcome message is displayed
    const welcomeMessage = page.getByText(/Welcome back/i);
    await expect(welcomeMessage).toBeVisible();
  });

  test('should handle Google OAuth failure and display error message', async ({ page }) => {
    // Click Google login button using getByRole
    const googleButton = page.getByRole('button', { name: /Sign in with Google/i });
    await expect(googleButton).toBeVisible();
    await googleButton.click();

    // Wait for Google OAuth redirect
    await page.waitForURL(/accounts\.google\.com/);

    // Intercept the Google API call and simulate failure
    await page.route('**/oauth2/v3/userinfo', route => {
      route.abort('failed');
    });

    // Click "Allow" button using getByRole
    const allowButton = page.getByRole('button', { name: /Allow/i });
    await expect(allowButton).toBeVisible();
    await allowButton.click();

    // Wait for error handling
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/Google authentication failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the login page
    const loginPage = page.getByRole('main');
    await expect(loginPage).toBeVisible();

    // Verify Google login button is still available
    const googleButton = page.getByRole('button', { name: /Sign in with Google/i });
    await expect(googleButton).toBeVisible();
  });
});
